const r=document.querySelector("#close"),l=document.querySelector("#modal-bg");r.addEventListener("click",e=>{e.preventDefault(),document.getElementById("modal").classList.add("hidden")});l.addEventListener("click",()=>{document.getElementById("modal").classList.add("hidden")});document.addEventListener("keydown",e=>{const t=document.getElementById("modal");e.key==="Escape"&&!t.classList.contains("hidden")&&t.classList.add("hidden")});const s=document.querySelectorAll(".delete-button");s.forEach(e=>{e.addEventListener("click",()=>{if(confirm("Voulez-vous vraiment supprimer la déclaration")){const o=document.getElementById("modal").querySelector("h2").getAttribute("data-date"),n="/supprimer-absences/"+userId+"/"+o;fetch(n,{method:"GET",headers:{"X-CSRF-TOKEN":document.querySelector('meta[name="csrf-token"]').getAttribute("content")}}),location.reload()}})});const m=document.querySelectorAll(".declaration-button");m.forEach(e=>{e.addEventListener("click",()=>{const t=document.getElementById("modal"),o=e.value,n=t.querySelector("h2").getAttribute("data-date"),d=t.querySelector("#hours_day"),c="/absences/"+userId+"/"+n+"/"+d.value+"/"+o;fetch(c,{method:"GET",headers:{"X-CSRF-TOKEN":document.querySelector('meta[name="csrf-token"]').getAttribute("content")}}).then(a=>{if(!a.ok)throw new Error("Network response was not ok")}).then(a=>{location.reload()}).catch(a=>{console.error("There was an error!")})})});const u=document.querySelectorAll(".info"),i=document.getElementById("modal");u.forEach(e=>{e.addEventListener("click",async()=>{const t=e.getAttribute("data-id"),o=await E(t),d=document.querySelector("#modalInfo").querySelector(".modal-body");d.innerHTML=o.note,i.classList.add("hidden")})});async function E(e){try{return await(await fetch("/trouver-declaration/"+e,{method:"GET",headers:{"X-CSRF-TOKEN":document.querySelector('meta[name="csrf-token"]').getAttribute("content")}})).json()}catch(t){console.error("There was an error:",t)}}
